class MarksheetMakerActivity:AppCompatActivity(){data class S(val n:String,val max:Int,val got:Int,val optional:Boolean);private lateinit var school:EditText;private lateinit var address:EditText;private lateinit var student:EditText;private lateinit var roll:EditText;private lateinit var clazz:EditText;private lateinit var exam:EditText;private lateinit var session:EditText;private lateinit var subjectBox:LinearLayout;private lateinit var preview:ImageView;private lateinit var status:TextView;private lateinit var save:Button;private var logo:Bitmap?=null;private var sheet:Bitmap?=null;private var unsaved=false;private var verificationId:String?=null;private val db=FirebaseFirestore.getInstance();private fun dp(v:Int)=(v*resources.displayMetrics.density).toInt();private fun rounded(c:String,r:Int)=GradientDrawable().apply{setColor(Color.parseColor(c));cornerRadius=dp(r).toFloat()}
override fun onCreate(b:Bundle?){super.onCreate(b);val root=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(18),dp(20),dp(18),dp(30));setBackgroundColor(Color.parseColor("#F6F7FC"))};root.addView(TextView(this).apply{text="Professional Marksheet Maker";textSize=26f;setTypeface(typeface,1);setTextColor(Color.parseColor("#17213D"))});root.addView(TextView(this).apply{text="Enter details and marks — preview updates instantly";setTextColor(Color.parseColor("#72798F"));setPadding(0,dp(5),0,dp(14))});val form=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(14),dp(10),dp(14),dp(14));background=rounded("#FFFFFF",18)};fun f(h:String)=EditText(this).apply{hint=h;background=rounded("#F7F8FC",10);setPadding(dp(12),dp(10),dp(12),dp(10));form.addView(this,LinearLayout.LayoutParams(-1,-2).apply{topMargin=dp(7)})};school=f("School Name");address=f("School Address / Contact / Code");student=f("Student Name");roll=f("Roll / Admission No.");clazz=f("Class / Section");exam=f("Exam Name");session=f("Academic Session");form.addView(Button(this).apply{text="Choose School Logo";isAllCaps=false;setOnClickListener{startActivityForResult(Intent(Intent.ACTION_OPEN_DOCUMENT).apply{type="image/*";addCategory(Intent.CATEGORY_OPENABLE)},401)}});root.addView(form);root.addView(TextView(this).apply{text="SUBJECTS & MARKS";setTypeface(typeface,1);setTextColor(Color.parseColor("#3157D5"));setPadding(0,dp(18),0,dp(7))});subjectBox=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL};root.addView(subjectBox);root.addView(Button(this).apply{text="＋ Add Subject";isAllCaps=false;setOnClickListener{addSubject()}});root.addView(TextView(this).apply{text="Optional subjects are shown on the marksheet but excluded from Total, Percentage and Pass/Fail.";textSize=12f;setTextColor(Color.parseColor("#72798F"));setPadding(0,dp(5),0,0)});root.addView(TextView(this).apply{text="LIVE PREVIEW";setTypeface(typeface,1);setTextColor(Color.parseColor("#3157D5"));setPadding(0,dp(18),0,dp(7))});preview=ImageView(this).apply{adjustViewBounds=true;scaleType=ImageView.ScaleType.FIT_CENTER;background=rounded("#FFFFFF",18)};root.addView(preview,LinearLayout.LayoutParams(-1,dp(430)));root.addView(Button(this).apply{text="Register Verification & Finalize";isAllCaps=false;setOnClickListener{generate()}},LinearLayout.LayoutParams(-1,-2).apply{topMargin=dp(12)});save=Button(this).apply{text="Save Marksheet PDF";isAllCaps=false;visibility=View.GONE;setOnClickListener{startActivityForResult(Intent(Intent.ACTION_CREATE_DOCUMENT).apply{type="application/pdf";addCategory(Intent.CATEGORY_OPENABLE);putExtra(Intent.EXTRA_TITLE,"EduNexa_Marksheet_${verificationId?:System.currentTimeMillis()}.pdf")},402)}};root.addView(save);status=TextView(this).apply{text="Live preview only • Nothing is registered or saved until you finalize.";setPadding(0,dp(10),0,0)};root.addView(status);setContentView(ScrollView(this).apply{addView(root)});val tw=watcher();listOf(school,address,student,roll,clazz,exam,session).forEach{it.addTextChangedListener(tw)};repeat(5){addSubject()};updatePreview()}
private fun watcher()=object:TextWatcher{override fun beforeTextChanged(s:CharSequence?,a:Int,b:Int,c:Int){};override fun onTextChanged(s:CharSequence?,a:Int,b:Int,c:Int){updatePreview()};override fun afterTextChanged(e:Editable?){}}
private fun addSubject(){val card=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(10),dp(8),dp(10),dp(8));background=rounded("#FFFFFF",14)};val row=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL};val name=EditText(this).apply{hint="Subject";addTextChangedListener(watcher())};val max=EditText(this).apply{hint="Max";inputType=2;addTextChangedListener(watcher())};val got=EditText(this).apply{hint="Marks";inputType=2;addTextChangedListener(watcher())};row.addView(name,LinearLayout.LayoutParams(0,-2,2f));row.addView(max,LinearLayout.LayoutParams(0,-2,1f));row.addView(got,LinearLayout.LayoutParams(0,-2,1f));card.addView(row);val bottom=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;gravity=Gravity.CENTER_VERTICAL};val optional=CheckBox(this).apply{text="Optional subject";setOnCheckedChangeListener{_,_->updatePreview()}};bottom.addView(optional,LinearLayout.LayoutParams(0,-2,1f));bottom.addView(Button(this).apply{text="Remove";isAllCaps=false;setOnClickListener{subjectBox.removeView(card);updatePreview()}});card.addView(bottom);card.tag=arrayOf(name,max,got,optional);subjectBox.addView(card,LinearLayout.LayoutParams(-1,-2).apply{bottomMargin=dp(8)});updatePreview()}
private fun rows():List<S>{val a=mutableListOf<S>();for(i in 0 until subjectBox.childCount){val v=subjectBox.getChildAt(i);@Suppress("UNCHECKED_CAST") val x=v.tag as? Array<View>?:continue;val n=(x[0] as EditText).text.toString().trim();val m=(x[1] as EditText).text.toString().toIntOrNull();val g=(x[2] as EditText).text.toString().toIntOrNull();val o=(x[3] as CheckBox).isChecked;if(n.isNotBlank()&&m!=null&&g!=null&&m>0&&g in 0..m)a.add(S(n,m,g,o))};return a}
private fun calc(r:List<S>):Triple<Int,Int,Double>{val main=r.filter{!it.optional};val max=main.sumOf{it.max};val got=main.sumOf{it.got};return Triple(max,got,if(max>0)got*100.0/max else 0.0)}
private fun updatePreview(){if(!::preview.isInitialized)return;val r=rows();val(max,got,pct)=calc(r);val main=r.filter{!it.optional};val result=if(main.isEmpty())"—" else if(main.all{it.got*100/it.max>=33})"PASS" else "FAIL";preview.setImageBitmap(drawSheet(r,max,got,pct,result,false,null))}
private fun drawSheet(r:List<S>,max:Int,got:Int,pct:Double,result:String,final:Boolean,id:String?):Bitmap{val w=900;val h=1180;val b=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);val c=Canvas(b);c.drawColor(Color.WHITE);val p=Paint(1).apply{color=Color.rgb(28,48,94)};c.drawRect(0f,0f,w.toFloat(),14f,p);p.textAlign=Paint.Align.CENTER;p.typeface=Typeface.DEFAULT_BOLD;p.textSize=38f;c.drawText(school.text.toString().ifBlank{"SCHOOL NAME"},w/2f,70f,p);p.typeface=Typeface.DEFAULT;p.textSize=16f;c.drawText(address.text.toString().ifBlank{"School address / contact"},w/2f,100f,p);logo?.let{c.drawBitmap(Bitmap.createScaledBitmap(it,75,75,true),30f,28f,null)};p.typeface=Typeface.DEFAULT_BOLD;p.textSize=25f;c.drawText("ACADEMIC MARKSHEET",w/2f,148f,p);p.textAlign=Paint.Align.LEFT;p.typeface=Typeface.DEFAULT;p.textSize=17f;c.drawText("Student: ${student.text.toString().ifBlank{"—"}}",42f,198f,p);c.drawText("Roll: ${roll.text.toString().ifBlank{"—"}}",490f,198f,p);c.drawText("Class: ${clazz.text.toString().ifBlank{"—"}}",42f,230f,p);c.drawText("Exam: ${exam.text.toString().ifBlank{"—"}}",490f,230f,p);c.drawText("Session: ${session.text.toString().ifBlank{"—"}}",42f,262f,p);var y=320f;p.typeface=Typeface.DEFAULT_BOLD;c.drawText("SUBJECT",42f,y,p);c.drawText("MAX",500f,y,p);c.drawText("MARKS",625f,y,p);c.drawText("GRADE",755f,y,p);p.typeface=Typeface.DEFAULT;r.take(12).forEach{s->y+=43;c.drawText((s.n+(if(s.optional)" (Optional)" else "")).take(35),42f,y,p);c.drawText(s.max.toString(),500f,y,p);c.drawText(s.got.toString(),625f,y,p);c.drawText(grade(s.got,s.max),755f,y,p)};y+=65;p.typeface=Typeface.DEFAULT_BOLD;p.textSize=19f;c.drawText("Main Total: $got / $max",42f,y,p);c.drawText("Percentage: ${if(max>0)"%.2f%%".format(pct) else "—"}",315f,y,p);c.drawText("Result: $result",680f,y,p);p.typeface=Typeface.DEFAULT;p.textSize=14f;c.drawText(if(final)"Verification ID: ${id?:"—"}" else "Live preview • Not registered yet",42f,h-60f,p);return b}
private fun generate(){val uid=FirebaseAuth.getInstance().currentUser?.uid?:run{status.text="Login required";return};val r=rows();if(school.text.isBlank()||student.text.isBlank()||r.none{!it.optional}){status.text="Enter school, student and at least one Main subject";return};val(max,got,pct)=calc(r);val result=if(r.filter{!it.optional}.all{it.got*100/it.max>=33})"PASS" else "FAIL";status.text="Registering verification...";db.collection("users").document(uid).get().addOnSuccessListener{u->val approved=u.getString("role")=="school"&&u.getBoolean("schoolApproved")==true;val id="EDX-"+UUID.randomUUID().toString().take(8).uppercase();verificationId=id;val record=hashMapOf<String,Any>("verificationId" to id,"issuerUid" to uid,"issuerApproved" to approved,"schoolName" to school.text.toString(),"studentName" to student.text.toString(),"rollNo" to roll.text.toString(),"className" to clazz.text.toString(),"examName" to exam.text.toString(),"session" to session.text.toString(),"subjects" to r.map{mapOf("name" to it.n,"max" to it.max,"obtained" to it.got,"optional" to it.optional)},"totalObtained" to got,"totalMax" to max,"percentage" to pct,"result" to result,"createdAt" to FieldValue.serverTimestamp());db.collection("marksheetVerifications").document(id).set(record).addOnSuccessListener{val small=drawSheet(r,max,got,pct,result,true,id);sheet=Bitmap.createScaledBitmap(small,1240,1754,true);preview.setImageBitmap(sheet);save.visibility=View.VISIBLE;unsaved=true;status.text="Registered • ID: $id • Tap Save PDF when ready."}.addOnFailureListener{status.text="Verification failed: ${it.message}"}}.addOnFailureListener{status.text="Account check failed: ${it.message}"}}
override fun onActivityResult(q:Int,res:Int,data:Intent?){super.onActivityResult(q,res,data);if(res!=Activity.RESULT_OK)return;if(q==401){logo=data?.data?.let{u->contentResolver.openInputStream(u)?.use{BitmapFactory.decodeStream(it)}};updatePreview()}else if(q==402){val uri=data?.data?:return;val bmp=sheet?:return;val pdf=PdfDocument();val page=pdf.startPage(PdfDocument.PageInfo.Builder(bmp.width,bmp.height,1).create());page.canvas.drawBitmap(bmp,0f,0f,null);pdf.finishPage(page);runCatching{contentResolver.openOutputStream(uri)?.use{pdf.writeTo(it)};unsaved=false;status.text="PDF saved • ID: $verificationId"}.onFailure{status.text="Save failed: ${it.message}"};pdf.close()}}
private fun grade(g:Int,m:Int)=when(g*100/m){in 90..100->"A+";in 80..89->"A";in 70..79->"B+";in 60..69->"B";in 50..59->"C";in 33..49->"D";else->"F"}
@Suppress("DEPRECATION") override fun onBackPressed(){if(unsaved)AlertDialog.Builder(this).setTitle("Discard unsaved PDF?").setMessage("Verification is registered, but PDF is not saved on this device.").setPositiveButton("Discard"){_,_->unsaved=false;super.onBackPressed()}.setNegativeButton("Stay",null).show()else super.onBackPressed()}}
